# ── CRIAR PRODUTOS ────────────────────────────────────────────────────────────

print(f"\n🌱 Importando {len(PRODUCTS)} produtos…\n")

ok = 0
skip = 0
fail = 0

for p in PRODUCTS:
    cat_key = f"{p['categoria']} > {p['subcategoria']}"
    cat_id = child_ids.get(cat_key)

    # fallback: tenta categoria-pai
    if not cat_id:
        cat_id = parent_ids.get(p["categoria"])

    price_cents = None
    if p["preco_atual"] and p["preco_atual"] > 0:
        price_cents = int(round(p["preco_atual"] * 100))

    name = p["nome"]
    slug = slugify(name)

    payload = {
        "name":        name,
        "slug":        slug,
        "description": p.get("descricao", ""),
        "price_cents": price_cents,
        "images":      p.get("imagens", []),
        "stock":       10,
        "is_active":   True,
        "category_ids": [cat_id] if cat_id else [],
    }

    r = req("POST", "/api/products", payload, TOKEN)
    if r and r.get("id"):
        ok += 1
        print(f"   ✅ [{ok:03d}] {name[:55]}")
    elif r is None:
        # tenta com slug modificado em caso de conflito
        payload["slug"] = slug + "-" + str(int(time.time() * 1000) % 10000)
        r2 = req("POST", "/api/products", payload, TOKEN)
        if r2 and r2.get("id"):
            ok += 1
            print(f"   ✅ [{ok:03d}] {name[:55]} (slug ajustado)")
        else:
            fail += 1
            print(f"   ❌ falhou: {name[:55]}")
    else:
        fail += 1
        print(f"   ❌ falhou: {name[:55]}")

    time.sleep(0.05)  # não sobrecarrega o servidor

print(f"\n{'='*50}")
print(f"✅ Criados: {ok}  ❌ Falhas: {fail}")
print(f"Acesse: http://localhost:8080/site/index.html")
